// Бере список товарів і випускає по одному повідомленню на кожен товар
// (далі вони йдуть через ноду-обмежувач швидкості і завантажуються по черзі).
const STORE = 'file';
const items = global.get('items', STORE) || [];
if (items.length === 0) {
    node.status({ fill: 'yellow', shape: 'ring', text: 'список порожній' });
    return null;
}

const manual = msg.manual === true;
const out = items.map(item => ({
    item: item,
    manual: manual,
    url: item.url,
    requestTimeout: 30000,
    headers: {
        'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/124.0.0.0 Safari/537.36',
        'Accept-Language': 'uk-UA,uk;q=0.9,en-US;q=0.8,en;q=0.7'
    }
}));

node.status({ fill: 'blue', shape: 'dot', text: 'перевірка: ' + out.length + ' поз.' });
return [out];

// Витягує ціну зі сторінки, порівнює з попередньою, оновлює історію і формує сповіщення.
const STORE = 'file';
const THRESHOLDS = [
    [25, '🔥 Падіння ціни більше 25%'],
    [20, '🔥 Падіння ціни 20%+'],
    [15, '📉 Падіння ціни 15%+'],
    [10, '📉 Падіння ціни 10%+'],
    [0,  '🔻 Ціна зменшилась']
];
const CUR = { UAH: '₴', USD: '$', EUR: '€' };

const esc = s => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const fmt = n => String(Math.round(n)).replace(/\B(?=(\d{3})+(?!\d))/g, ' ');
const toNum = s => parseFloat(String(s).replace(/[\s ]/g, '').replace(',', '.'));

const item = msg.item;
if (!item) return null;
const manual = msg.manual === true;

// 1) Помилка завантаження (403, таймаут, немає мережі тощо)
if (msg.error || !msg.statusCode || msg.statusCode >= 400) {
    const reason = msg.error ? (msg.error.message || String(msg.error)) : ('HTTP ' + msg.statusCode);
    node.warn('[' + item.name + '] помилка завантаження: ' + reason);
    return manual ? { text: '⚠️ <b>' + esc(item.name) + '</b>: не вдалося завантажити сторінку (' + esc(reason) + ').' } : null;
}

// 2) Пошук ціни
const html = typeof msg.payload === 'string' ? msg.payload : '';
let price = null;
let cur = item.currency || '';

if (item.type === 'auto_ria_search' || item.type === 'auto_ria_listing') {
    // На AUTO.RIA беремо поточну (не закреслену) ціну в доларах: "13 300 $ ·"
    const text = html.replace(/<[^>]+>/g, ' ').replace(/&nbsp;|&#160;/g, ' ');
    const found = [];
    // Ціна = цифри групами по три ("17 950") або суцільне число; не може починатись усередині іншого числа (рік тощо)
    const re = /(?<!\d)(\d{1,3}(?:\s\d{3})*|\d{4,7})\s?\$\s*·/g;
    let m;
    while ((m = re.exec(text)) !== null) {
        const v = toNum(m[1]);
        if (isFinite(v) && v > 0) found.push(v);
    }
    if (found.length) {
        price = item.type === 'auto_ria_search' ? Math.min.apply(null, found) : found[0];
        cur = '$';
    }
} else {
    // Магазини (comfy.ua та інші): мета-теги Open Graph / schema.org / JSON-LD
    const patterns = [
        /<meta[^>]+(?:property|name)=["']product:price:amount["'][^>]*content=["']([^"']+)["']/i,
        /<meta[^>]+content=["']([^"']+)["'][^>]+(?:property|name)=["']product:price:amount["']/i,
        /<meta[^>]+(?:property|name)=["']og:price:amount["'][^>]*content=["']([^"']+)["']/i,
        /itemprop=["']price["'][^>]*content=["']([^"']+)["']/i,
        /"price"\s*:\s*"?(\d[\d.]*)"?/
    ];
    for (const p of patterns) {
        const m = html.match(p);
        if (m) {
            const v = toNum(m[1]);
            if (isFinite(v) && v > 0) { price = v; break; }
        }
    }
    if (!cur) {
        const cm = html.match(/<meta[^>]+(?:property|name)=["'](?:product|og):price:currency["'][^>]*content=["']([A-Z]{3})["']/i)
                || html.match(/"priceCurrency"\s*:\s*"([A-Z]{3})"/);
        if (cm) cur = CUR[cm[1]] || cm[1];
    }
}

const prices = global.get('prices', STORE) || {};
const entry = prices[item.id] || { history: [] };

if (price === null) {
    node.warn('[' + item.name + '] ціну не знайдено — можливо, змінилась верстка');
    const first = !entry.warned;
    entry.warned = true;
    prices[item.id] = entry;
    global.set('prices', prices, STORE);
    if (manual || first) {
        return { text: '⚠️ <b>' + esc(item.name) + '</b>: не вдалось знайти ціну на сторінці.\n' + esc(item.url) };
    }
    return null;
}

// 3) Порівняння з попередньою ціною
const old = entry.last_price;
let text = null;
if (old !== undefined && old !== null && price < old) {
    const pct = (old - price) / old * 100;
    const label = THRESHOLDS.find(t => pct >= t[0])[1];
    text = label + '\n<b>' + esc(item.name) + '</b>\n' +
           'Було: ' + fmt(old) + ' ' + cur + '\n' +
           'Стало: ' + fmt(price) + ' ' + cur + '\n' +
           'Падіння: ' + pct.toFixed(1) + '%\n' + esc(item.url);
} else if (manual) {
    const status = (old === undefined || old === null) ? 'базову ціну збережено'
                 : price > old ? 'ціна зросла (було ' + fmt(old) + ')'
                 : 'без змін';
    text = 'ℹ️ <b>' + esc(item.name) + '</b>: ' + fmt(price) + ' ' + cur + ' — ' + status;
}

// 4) Зберігаємо стан (історія — останні 180 записів)
entry.last_price = price;
entry.currency = cur;
entry.name = item.name;
entry.url = item.url;
entry.warned = false;
entry.history = (entry.history || []).concat({ date: new Date().toISOString(), price: price }).slice(-180);
prices[item.id] = entry;
global.set('prices', prices, STORE);

node.status({ fill: 'green', shape: 'dot', text: item.name.slice(0, 24) + ': ' + fmt(price) });
return text ? { text: text } : null;

// Готує запит sendMessage до Telegram API. Токен береться зі змінної середовища.
const token = env.get('TELEGRAM_BOT_TOKEN');
const chat = msg.chat_id || env.get('TELEGRAM_CHAT_ID');
if (!token || !chat) {
    node.status({ fill: 'red', shape: 'ring', text: 'нема TELEGRAM_BOT_TOKEN / TELEGRAM_CHAT_ID' });
    node.warn('Змінні середовища TELEGRAM_BOT_TOKEN / TELEGRAM_CHAT_ID не задані — повідомлення не надіслано');
    return null;
}
if (!msg.text) return null;

const base = env.get('TELEGRAM_API_BASE') || 'https://api.telegram.org';
return {
    url: base + '/bot' + token + '/sendMessage',
    headers: { 'content-type': 'application/json' },
    requestTimeout: 20000,
    payload: {
        chat_id: chat,
        text: String(msg.text).slice(0, 4000),
        parse_mode: 'HTML',
        disable_web_page_preview: true
    }
};

// Формує запит getUpdates (опитування Telegram на нові команди). Запускається кожні 5 секунд.
const token = env.get('TELEGRAM_BOT_TOKEN');
if (!token) {
    node.status({ fill: 'red', shape: 'ring', text: 'нема TELEGRAM_BOT_TOKEN' });
    return null;
}

// Захист від накладання запитів: якщо попередній ще не завершився, пропускаємо цикл
const now = Date.now();
const lock = flow.get('pollLock');
if (lock && now - lock < 20000) return null;
flow.set('pollLock', now);

const base = env.get('TELEGRAM_API_BASE') || 'https://api.telegram.org';
const offset = global.get('tg_offset', 'file') || 0;
return {
    url: base + '/bot' + token + '/getUpdates?timeout=0&offset=' + offset,
    requestTimeout: 15000,
    headers: {}
};

// Обробка команд Telegram: /start /help /add /list /remove /check
// Вихід 1 -> відповіді в Telegram, вихід 2 -> запуск ручної перевірки цін.
const STORE = 'file';
const esc = s => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const fmt = n => String(Math.round(n)).replace(/\B(?=(\d{3})+(?!\d))/g, ' ');
const hash = s => { let h = 5381; for (let i = 0; i < s.length; i++) h = ((h << 5) + h + s.charCodeAt(i)) | 0; return (h >>> 0).toString(36); };

const HELP = [
    '🤖 <b>Монітор цін</b>',
    '',
    '/add &lt;посилання&gt; [назва] — додати товар',
    '/list — показати відстежувані товари',
    '/remove &lt;номер або id&gt; — видалити товар',
    '/check — перевірити ціни зараз',
    '/help — ця підказка',
    '',
    'Щодня бот перевіряє ціни сам і пише, якщо ціна впала.'
].join('\n');

flow.set('pollLock', null);   // запит завершено, можна опитувати знову

const data = msg.payload;
if (!data || data.ok !== true) {
    if (msg.statusCode) node.warn('getUpdates: HTTP ' + msg.statusCode);
    node.status({ fill: 'red', shape: 'ring', text: 'getUpdates: ' + (msg.statusCode || 'помилка') });
    return null;
}
node.status({ fill: 'green', shape: 'dot', text: 'ок ' + new Date().toLocaleTimeString() });

const allowed = String(env.get('TELEGRAM_CHAT_ID') || '').trim();
let items = global.get('items', STORE) || [];
let prices = global.get('prices', STORE) || {};
let offset = global.get('tg_offset', STORE) || 0;
const replies = [];
let runCheck = false;
let changed = false;

for (const u of (data.result || [])) {
    offset = Math.max(offset, u.update_id + 1);
    const m = u.message;
    if (!m || typeof m.text !== 'string') continue;

    const chatId = String(m.chat.id);
    const say = text => replies.push({ chat_id: chatId, text: text });
    const parts = m.text.trim().split(/\s+/);
    const cmd = parts[0].split('@')[0].toLowerCase();

    // Якщо TELEGRAM_CHAT_ID ще не задано, відповідаємо лише на /start і показуємо chat_id
    if (!allowed) {
        if (cmd === '/start') {
            say('👋 Твій chat_id: <code>' + esc(chatId) + '</code>\nЗадай його у змінній середовища TELEGRAM_CHAT_ID і перезапусти Node-RED.');
        }
        continue;
    }
    // Чужі чати ігноруємо
    if (chatId !== allowed) {
        node.warn('Команда з чужого чату ' + chatId + ' проігнорована');
        continue;
    }

    switch (cmd) {
        case '/start':
        case '/help':
            say(HELP);
            break;

        case '/add': {
            const url = parts[1];
            if (!url || !/^https?:\/\/[^\s]+$/i.test(url)) {
                say('Використання: <code>/add &lt;посилання&gt; [назва]</code>');
                break;
            }
            if (items.some(i => i.url === url)) {
                say('ℹ️ Це посилання вже відстежується.');
                break;
            }
            const host = url.replace(/^https?:\/\//i, '').split(/[\/?#]/)[0].toLowerCase().replace(/^www\./, '');
            const path = url.replace(/^https?:\/\/[^\/?#]+/i, '').split(/[?#]/)[0];
            let type = 'generic';
            let currency = '';
            let name = parts.slice(2).join(' ');
            if (/(^|\.)comfy\.ua$/.test(host)) {
                type = 'comfy_product'; currency = '₴';
                if (!name) name = 'Comfy: ' + (path.split('/').filter(Boolean).pop() || host).replace(/\.html?$/i, '').replace(/[-_]+/g, ' ').slice(0, 70);
            } else if (/(^|\.)auto\.ria\.com$/.test(host)) {
                type = /\/search\b/.test(path) ? 'auto_ria_search' : 'auto_ria_listing';
                currency = '$';
                if (!name) name = type === 'auto_ria_search' ? 'AUTO.RIA — пошук' : 'AUTO.RIA — оголошення';
            } else if (!name) {
                name = host + ': ' + (path.split('/').filter(Boolean).pop() || '').replace(/\.html?$/i, '').replace(/[-_]+/g, ' ').slice(0, 60);
            }
            const id = host.replace(/\W+/g, '_') + '_' + hash(url);
            items.push({ id: id, name: name, url: url, type: type, currency: currency });
            changed = true;
            say('✅ Додано: <b>' + esc(name) + '</b>\nТип: ' + type + '\nПерша ціна збережеться при найближчій перевірці (або команда /check).');
            break;
        }

        case '/list': {
            if (!items.length) {
                say('Список порожній. Додай товар: <code>/add &lt;посилання&gt;</code>');
                break;
            }
            const lines = items.map((it, i) => {
                const p = prices[it.id];
                const priceTxt = p && p.last_price != null ? fmt(p.last_price) + ' ' + (p.currency || it.currency || '') : 'ще не перевірено';
                return (i + 1) + '. <b>' + esc(it.name) + '</b> — ' + priceTxt + '\n    id: <code>' + esc(it.id) + '</code>';
            });
            say('📋 Відстежується (' + items.length + '):\n\n' + lines.join('\n'));
            break;
        }

        case '/remove':
        case '/del': {
            const arg = parts[1];
            if (!arg) { say('Використання: <code>/remove &lt;номер або id&gt;</code>'); break; }
            const idx = /^\d+$/.test(arg) ? parseInt(arg, 10) - 1 : items.findIndex(i => i.id === arg);
            if (idx < 0 || idx >= items.length) { say('❌ Не знайшов такої позиції. Дивись /list'); break; }
            const removed = items.splice(idx, 1)[0];
            delete prices[removed.id];
            changed = true;
            say('🗑 Видалено: <b>' + esc(removed.name) + '</b>');
            break;
        }

        case '/check':
            if (!items.length) {
                say('Список порожній. Додай товар: <code>/add &lt;посилання&gt;</code>');
            } else {
                say('⏳ Перевіряю ціни (' + items.length + ' поз.)…');
                runCheck = true;
            }
            break;

        default:
            if (cmd.startsWith('/')) say('Невідома команда. Напиши /help');
    }
}

global.set('tg_offset', offset, STORE);
if (changed) {
    global.set('items', items, STORE);
    global.set('prices', prices, STORE);
}
return [replies.length ? replies : null, runCheck ? { manual: true } : null];

// Ініціалізація: при першому запуску записуємо стартовий список товарів у файлове сховище.
const STORE = 'file';
const DEFAULT_ITEMS = [
    {
        id: 'comfy_galaxy_a17',
        name: 'Samsung Galaxy A17 8/256Gb Gray (Comfy)',
        url: 'https://comfy.ua/ua/smartfon-samsung-galaxy-a17-8-256gb-gray-sm-a175fzaeeuc.html',
        type: 'comfy_product',
        currency: '₴'
    },
    {
        id: 'auto_ria_bolt_ev_search',
        name: 'Chevrolet Bolt EV — пошук на AUTO.RIA',
        url: 'https://auto.ria.com/uk/search/?abroad=0&customs_cleared=1&all%5B0%5D.any%5B0%5D.brand=13&all%5B0%5D.any%5B0%5D.any%5B0%5D.model=51091&query=chevrolet+bolt+ev',
        type: 'auto_ria_search',
        currency: '$'
    }
];

if (global.get('items', STORE) === undefined) {
    global.set('items', DEFAULT_ITEMS, STORE);
    node.status({ fill: 'green', shape: 'dot', text: 'стартовий список записано' });
} else {
    const n = (global.get('items', STORE) || []).length;
    node.status({ fill: 'grey', shape: 'dot', text: 'позицій у списку: ' + n });
}
return null;
